      ]
    },
    {
      "name": "filtering",
      "targets": [
        "features/filtering.feature:All filter shows every todo",
        "features/filtering.feature:Active filter shows only incomplete todos",
        "features/filtering.feature:Completed filter shows only completed todos",
        "features/filtering.feature:Completing a todo hides it from the Active filter",
        "features/filtering.feature:Active filter is selected by default"
      ]
    },
    {
      "name": "persistence",
      "targets": [
        "features/persistence.feature:Todos persist across page reload",
        "features/persistence.feature:Completed state persists across reload",
        "features/persistence.feature:Todos are stored under the correct localStorage key"
      ]
    },
    {
      "name": "routing",
      "targets": [
        "features/routing.feature:Default route shows all todos",
        "features/routing.feature:Active route shows active todos",
        "features/routing.feature:Completed route shows completed todos",
        "features/routing.feature:Clicking a filter link changes the route"
      ]
    }
  ]
}

